	}
	catch (const std::exception&amp; e)
	{
		std::cerr &lt;&lt; &quot;Client &quot; &lt;&lt; id &lt;&lt; &quot; exception: &quot; &lt;&lt; e.what() &lt;&lt; std::endl;
	}
}
