개발-(cs)/언어/c++/[c++]-template-(함수-템플릿).content:
Template (함수 템플릿)
이 노트는 C++ 함수 템플릿의 기본 형태, 여러 타입을 받는 다중 템플릿 인자, 그리고 함수 템플릿 특수화를 정리한다. 함수 템플릿은 코드 재사용성과 타입 안정성을 높여주지만 복잡성과 컴파일 시간 증가라는 트레이드오프가 있으며, 특정 인자 타입(예: 사용자 정의 클래스)에 대해서만 다른 동작을 하도록 특수화할 수 있다.

함수 템플릿 형태   
함수 템플릿 특징   
함수 템플릿 특수화

함수 템플릿 형태
//template&lt;typename T&gt;
template&lt;class T&gt;
void Print(T a)
{
	cout &lt;&lt; a &lt;&lt; endl;
}

int main()
{
	// 여러 타입을 받을 수 있다 (함수 템플릿)
	Print(50);
	Print&lt;int&gt;(50.f); //명시적으로도 가능
	Print(50.f);
	Print(50.0);
	Print(&quot;Hello&quot;);
}

템플릿이 사용되는 함수 위에 template 정의
template&lt;class [템플릿타입이름]&gt;  또는 template&lt;typename [템플릿타입이름]&gt;
다양한 타입을 받을 수 있는 형태

template&lt;typename A, typename B, typename C&gt;
서로다른 A,B,C 타입 3개를 받을 수 있다



template&lt;class T, class A, class B&gt;
void Print(T t, A a, B b)
{
	cout &lt;&lt; t &lt;&lt; endl;
	cout &lt;&lt; a &lt;&lt; endl;
	cout &lt;&lt; b &lt;&lt; endl;

}

int main()
{
	// 여러 타입을 받을 수 있다 (함수 템플릿)
	Print(50,&quot;Hello&quot;,12.3);
	Print&lt;int, double, float&gt;(3.f, 50, 50.f); //명시적으로도 가능

}
함수 템플릿 특징

장점

코드 재사용성이 높다
타입 안정성
유연하게 코드 작성 가능


단점

복잡성 증가
가독성 문제
컴파일 시간 증가



함수 템플릿 특수화

템플릿은 어느 타입이든 받을 수 있으므로, 정의되어있는 함수 및 클래스를 이용하게 된다.
이럴때 원하는 인자 타입이 들어올때는 다른 함수를 호출하게 하기 위해서 템플릿 특수화 기능 사용

class Knight
{
public:
	int _hp = 15;

};

template&lt;typename T&gt;
void Print(T a)
{
	cout &lt;&lt; a &lt;&lt; endl;
}

// 템플릿 특수화 (Knight 인자가 들어오면 밑에 구현된 Print가 호출됨)
template&lt;&gt;
void Print(Knight a)
{
	cout &lt;&lt; &quot;Knight!!!!&quot; &lt;&lt; endl;
	cout &lt;&lt; a._hp &lt;&lt; endl;

}

int main()
{
	Knight k1;	
	Print(k1);
	return 0;
}

개발-(cs)/언어/c++/[c++]-static.content:
static
이 노트는 C++에서 static 키워드가 붙는 변수/함수의 생존 기간과 접근 범위, 그리고 함수 내 정적 변수·클래스 정적 멤버·정적 전역 함수 등 사용 종류를 정리한다. static으로 선언된 데이터는 프로그램 시작부터 종료까지 유지되며, 클래스 정적 멤버는 모든 객체가 공유해야 하는 값을 관리할 때, 파일 범위의 정적 함수/변수는 해당 파일 내부로 접근을 제한하고 싶을 때 사용한다.
static
Static

생존시기 

프로그램 시작 ~ 종료까지
해당 데이터를 그대로 유지


접근 방법

클래스 내부에서 static을 사용했을 시, 클래스 이름을 통해 호출 가능

멤버함수 , 멤버 변수에 적용 가능


일반 함수에 static을 사용했을 시, 해당 함수 범위내에서 접근 가능
전역으로 사용했을 시, 해당 파일 내에서 접근 가능


사용이유

메모리에 유지해야하는 값이 존재해야할 경우 사용
클래스에서 모든 객체에 동일하게 사용되어야할경우 사용


static 사용 종류

함수 내 정적 변수
클래스 내 정적 변수
클래스 내 정적 함수
정적 전역 변수 및 함수



class StaticTest
{
public:
	//정적 멤버 함수
	void static Print()
	{
		cout &lt;&lt; &quot;StaticTest class()&quot; &lt;&lt; endl;
	}

public:
	// 정적 멤버 변수
	static int _fix_count;
};

// 정적 함수 
int Test()
{
	// 정적함수 내 변수
	// 해당 Test()함수 내부에서만 사용 가능
	static int s_id = 1;
	return s_id++;
}

// 정적 함수 static
// 해당 파일 내부에서만 사용 가능
static void ExternTest()
{
	cout &lt;&lt; &quot;ExternTest() &quot; &lt;&lt; endl;
}

//전역으로 초기화 진행 (클래스외부에서 정의해야함)
// main 함수내부에서 초기화를 진행할경우 오류

int StaticTest::_fix_count;

int main()
{
	StaticTest::_fix_count = 5;
	StaticTest::Print();

	StaticTest s;
	cout &lt;&lt; s._fix_count &lt;&lt; endl;

	for (int i = 0; i &lt; 5; i++)
	{
		cout &lt;&lt; Test() &lt;&lt; endl;
	}
}

개발-(cs)/언어/c++/[c++]-static_cast,-dynami.content:
static_cast, dynamic_cast, const_cast, reinterpret_cast
이 노트는 C++의 네 가지 캐스팅 연산자 static_cast, dynamic_cast, const_cast, reinterpret_cast의 용도와 예제를 정리한다. static_cast는 C스타일 캐스팅보다 안전한 일반적인 타입 변환에, dynamic_cast는 RTTI를 이용해 실패 시 nullptr/bad_cast를 반환하는 안전한 다운캐스팅에, const_cast는 const 제거/추가에, reinterpret_cast는 가장 위험하지만 어떤 타입으로든 강제 변환이 가능한 경우에 사용한다.

static_cast
dynamic_cast
const_cast
reinterpret_cast

Static_cast

일반적으로 많이 사용되는 캐스팅
C스타일 ( (double) num; ) ”()” 보다 안전한 타입변환 방법

Static_cast 종류

기본 타입 간 변화

int i = 10;
double b = static_cast&lt;double&gt; i;

포인터 간의 변화 (** 주로 많이 사용)

class Base
{};
class Child : public Base
{};

Base* basePtr = new Child;
Child* childPtr = static_cast&lt;Child*&gt;(basePtr);

void 포인터 특정 포인터로 변환

void *ptr = &amp;i;
int* intPtr = static_cast&lt;int*&gt;(ptr);

열거형과 정수형 간의 변환

enum Player { Human, Monster };
Player player = Human;
int playerInt = static_cast&lt;int&gt;(player);
Dynamic_cast

RTTI사용 : Run Time Type Information
virtual을 사용해서 RTTI를 사용해야함 ( virtual을 사용하면 가상 테이블이 생성 == RTTI 정보 )

소멸자에 virtual을 사용



Dynamic_cast 종류

부모 -&gt; 자식으로 가능 캐스팅 (다운캐스팅)

class Base
{
public:
     virtual ~Base()
     {};
}

class Player : public Base
{}

int main
{
    Base* basePtr = new Player(); // Player기본생성자 호출

    Player* playerPtr = dynamic_cast&lt;Player*&gt;(basePtr);
    // 실패하면 -&gt; playerPtr에 nullptr이 반환됨 (안정성)
    return 0;
}

참조 타입 캐스팅

class Base
{
public:
     virtual ~Base()
     {};
}

class Player : public Base
{}

int main
{
    Base* basePtr = new Player(); // Player기본생성자 호출


    try 
    {
        Player&amp; player = dynamic_cast&lt;Player&amp;&gt;(*basePtr);
        // 실패하면 std::bad_cast 반환
    } catch (const std::bad_cast&amp; e)
    {
        std::cout &lt;&lt; &quot;dynamic_cast to Derived1&amp; failed: &quot; &lt;&lt; e.what() &lt;&lt; std::endl;
    }    


    return 0;
}
