// USER 가 typedef로 정의되기전에 구조체 안에서 자기참조 포인터가 사용되므로 &quot;struct USER*&quot; 사용 


공용체
[C언어] 공용체(Union) 완벽 정리: IP 주소 예제로 이해하기
1. 공용체(Union)란?


구조체(struct)는 각 멤버 변수가 독립적인 메모리 공간을 차지합니다.


공용체(union)는 모든 멤버 변수가 동일한 메모리 시작 주소를 공유(Overlap)합니다.


메모리 크기: 멤버 변수 중 가장 크기가 큰 타입의 크기로 결정됩니다.





                  NOTE



언제 사용할까?
하나의 메모리 공간을 상황에 따라 다양한 관점(전체 4바이트 정수로 보거나, 1바이트 4개로 쪼개서 볼 때 등)으로 다룰 때 사용합니다. (예: 네트워크 패킷 파싱, 하드웨어 레지스터 제어)


2. 예제: IP 주소와 4바이트 정수 매핑
IPv4 주소(192.168.0.1)는 점으로 구분된 1바이트 크기의 숫자 4개이면서, 동시에 하나의 32비트(4바이트) 정수입니다.
#include &lt;stdio.h&gt;
#include &lt;stdint.h&gt;

// 4바이트 크기의 공용체 정의
typedef union _IP_ADDR 
{
    uint32_t number;        // 4바이트 부호 없는 정수 관점
    unsigned char ip[4];    // 1바이트 단위 4개 배열 관점
} IP_ADDR;

int main(void)
{
    IP_ADDR data = {0};

    // 1. 1바이트 배열(ip)로 값 대입
    data.ip[0] = 192; // 0xC0
    data.ip[1] = 168; // 0xA8
    data.ip[2] = 0;   // 0x00
    data.ip[3] = 1;   // 0x01

    // 2. 출력하여 메모리 공유 확인
    printf(&quot;IP 주소 표기  : %d.%d.%d.%d\n&quot;, data.ip[0], data.ip[1], data.ip[2], data.ip[3]);
    printf(&quot;정수 10진수 표기: %u\n&quot;, data.number);
    printf(&quot;정수 16진수 표기: 0x%08X\n&quot;, data.number);

    return 0;
}

실행 결과
IP 주소 표기  : 192.168.0.1
정수 10진수 표기: 16820416
정수 16진수 표기: 0x0100A8C0

3. 메모리 구조 및 바이트 순서 (Endianness)
위 실행 결과에서 0xC0A80001이 아니라 0x0100A8C0으로 출력되는 이유는 x86/x64 환경의 리틀 엔디안(Little-Endian) 방식 때문입니다.
[메모리 주소 낮은 쪽] ──────────────────────────► [메모리 주소 높은 쪽]
┌──────────────┬──────────────┬──────────────┬──────────────┐
│    ip[0]     │    ip[1]     │    ip[2]     │    ip[3]     │
├──────────────┼──────────────┼──────────────┼──────────────┤
│  192 (0xC0)  │  168 (0xA8)  │   0 (0x00)   │   1 (0x01)   │
└──────────────┴──────────────┴──────────────┴──────────────┘
 ▲ LSB (최하위 바이트)                         ▲ MSB (최상위 바이트)

 ──► uint32_t number로 읽을 때: 0x01 00 A8 C0 (16,820,416)


































구분바이트 0바이트 1바이트 2바이트 3ip 배열ip[0] (0xC0)ip[1] (0xA8)ip[2] (0x00)ip[3] (0x01)리틀 엔디안 기준LSB (최하위)MSB (최상위)number 변수\multicolumn{4}{c}{0x0100A8C0}
4. 핵심 포인트 요약


메모리 절약 및 다중 관점 접근: sizeof(IP_ADDR)는 8바이트가 아닌 4바이트입니다.


타입 안전성(uint32_t): int 대신 uint32_t나 unsigned int를 사용하여 부호 비트(MSB)로 인한 원치 않는 음수 처리를 방지합니다.


엔디안 주의: 하드웨어/OS 아키텍처에 따라 바이트 배치 순서(빅 엔디안 vs 리틀 엔디안)가 달라질 수 있습니다.



구조체 메모리 할당 (+ 전처리기 pragma)
[C언어] 구조체 메모리 정렬(Padding) 및 1바이트 패킹 요약
1. 기본 정렬 원리: struct DATA
구조체 크기는 단순 합산(4 + 1 + 5 = 10바이트)이 아니라, 가장 큰 멤버 자료형(int = 4바이트)의 배수에 맞춰 끝에 패딩이 붙습니다.
Plaintext
[ 0 ][ 1 ][ 2 ][ 3 ]  --&gt; int num (4B)
[ 4 ]                  --&gt; char ch (1B)
[ 5 ][ 6 ][ 7 ][ 8 ][ 9 ]  --&gt; char list[5] (5B)
[10 ][11 ]             --&gt; [패딩 2B] (4의 배수 맞춤용)
─────────────────────────────────────────────────
총 크기: 12바이트




                  TIP



ch와 list[5] 사이에 패딩이 없는 이유: char는 1바이트 단위 정렬이므로 오프셋 5번 자리에서 바로 시작해도 CPU 접근에 문제가 없기 때문입니다.


2. 1바이트 단위 패킹 (#pragma pack)
패딩 없이 데이터 원본 크기 그대로(10바이트) 정렬하려면 #pragma pack(push, 1)과 #pragma pack(pop)을 사용합니다.
핵심 전처리기 사용법


#pragma pack(push, 1) : 이전 정렬 상태를 백업하고 1바이트 정렬 적용


#pragma pack(pop) : 원래 정렬 상태로 복원 (다른 코드/헤더 오염 방지)


3. 비교 코드 및 실행 결과
C
#include &lt;stdio.h&gt;
#include &lt;stddef.h&gt;

// 1. 기본 정렬 (4바이트 기준 패딩 삽입 -&gt; 12바이트)
struct DATA {
    int num;        // 4B (offset: 0)
    char ch;        // 1B (offset: 4)
    char list[5];   // 5B (offset: 5)
                    // 2B 패딩 (offset: 10~11)
};

// 2. 1바이트 패킹 (패딩 제거 -&gt; 10바이트)
#pragma pack(push, 1)
struct PACKED_DATA {
    int num;        // 4B (offset: 0)
    char ch;        // 1B (offset: 4)
    char list[5];   // 5B (offset: 5)
};
#pragma pack(pop)

int main(void)
{
    printf(&quot;[기본 정렬] struct DATA 크기        : %zu 바이트\n&quot;, sizeof(struct DATA));
    printf(&quot;  └ offset -&gt; num:%zu, ch:%zu, list:%zu\n\n&quot;, 
           offsetof(struct DATA, num), offsetof(struct DATA, ch), offsetof(struct DATA, list));

    printf(&quot;[1바이트 패킹] struct PACKED_DATA 크기: %zu 바이트\n&quot;, sizeof(struct PACKED_DATA));
    printf(&quot;  └ offset -&gt; num:%zu, ch:%zu, list:%zu\n&quot;, 
           offsetof(struct PACKED_DATA, num), offsetof(struct PACKED_DATA, ch), offsetof(struct PACKED_DATA, list));

    return 0;
}

실행 결과
Plaintext
[기본 정렬] struct DATA 크기        : 12 바이트
  └ offset -&gt; num:0, ch:4, list:5

[1바이트 패킹] struct PACKED_DATA 크기: 10 바이트
  └ offset -&gt; num:0, ch:4, list:5

개발-(cs)/언어/c언어/[cs]-알고리즘---핵심-개념-및-특징-정리.content:
알고리즘



                  NOTE



C 연결리스트(Linked List) 구조·순회 방법과 리눅스 커널의 list_for_each_entry() 매크로.


📌 개념
연결리스트

구조체 특징 (예: struct node* next)

구조체 선언 시 해당 구조체 크기만큼 저장 공간이 할당됨


재귀적으로 node 구조체가 사용됨
node 구조체

next를 가리키는 node 포인터
data 영역의 data 값들 존재
node ( node, data )























node1node2node1→next⇒node2datadata




















node2node3node2→next⇒node3datadata
list_for_each_entry() 함수



                  NOTE



#include &lt;linux/list.h&gt;



linked list의 node를 순서대로 접근
파라미터

pos : 루프 문에 사용할 커서로써 항목을 임시로 저장
head : 리스트의 헤드로, 연결리스트의 시작 주소
member : node 링크드 리스트 멤버 변수



💻 예시
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct node{
    char *data; //연결리스트 가지고 있는 data 영역
    struct node* next;//연결리스트 다음 공간 할당 (data , node)
}NODE;

int main(){
    NODE* head = NULL; //시작지점 (data시작지점)
    head = (NODE*)malloc(sizeof(NODE));
    head-&gt;data = &quot;start&quot;;

    NODE* node1=(NODE*)malloc(sizeof(NODE));
    head-&gt;next = node1; // 현재위치 -&gt; head
    node1-&gt;data = &quot;monday&quot;;

    NODE* node2 = (NODE*)malloc(sizeof(NODE));
    node1-&gt;next = node2;// 현재위치 -&gt; node1
    node2-&gt;data = &quot;tuesday&quot;;

    NODE* node3 = (NODE*)malloc(sizeof(NODE));
    node2-&gt;next = node3; // 현재위치 -&gt; node2
    node3-&gt;data=&quot;wendsday&quot;;
    node3-&gt;next=NULL; // 현재위치 -&gt; node3

    NODE* tmp =head;
    /*
    head &lt;- tmp 시작
    [node영역]
    head -&gt; node1 -&gt; node2 -&gt; node3 -&gt; NULL (반복문 종료)

    [data영역]
    head-&gt;data = start
    node1-&gt;data = monday
    node2-&gt;data = tuesday
    node3-&gt;data = wendsday
    node3-&gt;NULL = 종료

    */
    while(tmp != NULL){
//*주의 (while ( tmp-&gt;next != NULL ) )
// 마지막 node에서 next는 NULL을 가리키므로 마지막 노드의 데이터를 가져오지 못함
// cf : do - while와 반대되는 의미 *(조건을 만족하지 않아도 한번은 수행)
        printf(&quot;%s\n&quot;,tmp-&gt;data);
        tmp= tmp-&gt;next;
    }
    return 0;
}

개발-(cs)/언어/c언어/[cs]-자료형---핵심-개념-및-특징-정리.content:
자료형



                  NOTE



C 언어의 구조체(struct), 문자열, size_t/ssize_t, extern, typedef, enum 등 자료형 정리.


📌 개념
Struct (구조체)

구조체 형식

struct point
{
	//멤버변수
	int x;
	char *name;
	int y;
};

구조체 선언

//1.
struct point p1,p2,p3; // 구조체 만든 후 변수 선언

//2.
struct point{
	int x;
	int y;
}p1,p2,p3; // 구조체 만듬과 동시에 선언

구조체 초기화

//선언과 동시에 초기화 가능
struct point p1 = {1,&quot;park&quot;,3};

//선언 후 따로 초기화 불가능
struct point p1;
p1= {1,&quot;park&quot;,3};

구조체 대입 (다른 사칙 연산자 사용 불가)

struct point{
	int x;
	char*name;
	int y;
};

struct point pos;

pos.x = 1;
pos.name=&quot;park&quot;;
pos.y = 2;

구조체 연산 불가

struct point{
	int x;
	char*name;
	int y;
};

struct point2{
	int x;
	char* name;
	int y;
};

struct point pos = {10,&quot;park&quot;,20};
struct point2 pos1 = {10,&quot;park&quot;,20};

pos == pos1  // 불가능 (자료형이 서로 다르기 때문에)

중첩 구조체

#include &lt;stdio.h&gt;

struct class{
	int grade; //학년
	int class; //반
};

struct student{
	char * name;
//중첩된 구조체 선언
	struct class s; //구조체 변수 s를 구조체 student의 멤버 변수로 사용 (=중첩 구조체)
};


int main(){
	struct student s1;
	s1.name = &quot;홍길동&quot;;
	s1.s.grade = 2; //2학년
	s1.s.class = 3;  //3반

	printf(&quot;%s은 %d학년 %d반 입니다.&quot;, s1.name, s1.s.grade, s1.s.class);

	return 0;
}

중첩구조체 초기화

struct student s1 = {&quot;홍길동&quot;,{2,3}};

// or

struct student s1 = {&quot;홍길동&quot;,2,3}; //컴퓨터는 입력값을 순서대로 넣기 떄문에

구조체 배열 (멤버변수로 배열 사용 가능. 단, 배열 대입 연산 시 주의)

#include &lt;stdio.h&gt;

struct student
{
	char name[100]; //구조체 멤버 변수에 배열을 사용해도 무관함.
	int code; //학번
	int grade; //학년
	int class; //반

}; //student 구조체를 Student로 쓴다.

int main(){
	struct student stu;
	stu.name = &quot;홍길동&quot;; //오류 발생
	strcpy(stu.name, &quot;홍길동&quot;);
	return 0;
}
/*
오류발생 이유
- name이 배열 이름이므로 값을 할당할 수 없음
( 배열이름 == 주소값 // 배열이름 = 시작주소)
=&gt; strcpy 사용 해야함
*/

구조체 포인터

* 연산은 p보다 나중이므로 괄호 ()를 사용해야 함
접근: (*p).name == p-&gt;name
p-&gt;name에서 -&gt; 화살표는 구조체 포인터에서만 사용 가능 (struct student *p = &amp;stu)



#include &lt;stdio.h&gt;

struct student
{
	char * no;
	char * name;
	int grade;
	int class;
};

int main(){
	struct student stu = {&quot;20210000&quot;, &quot;Hong&quot;, 1, 3};
	struct student * p = &amp;stu; //구조체 포인터로 구조체 변수 stu 주소 가리키기.

	printf(&quot;학번 : %s 이름 : %s %d학년 %d반\n&quot;, stu.no, stu.name, stu.grade, stu.class); //구조체 변수로 일반적인 접근
	printf(&quot;학번 : %s 이름 : %s %d학년 %d반\n&quot;, (*p).no, (*p).name, (*p).grade, (*p).class); //구조체 포인터로 간접 접근 (*p 로 접근해야 함을 유의.)
	printf(&quot;학번 : %s 이름 : %s %d학년 %d반\n&quot;, p-&gt;no, p-&gt;name, p-&gt;grade, p-&gt;class);

	return 0;
}



                  NOTE



구조체의 주소 = 첫 멤버변수의 주소 (예: &amp;stu == &amp;stu.no)



자기참조 구조체 (자기 자신(구조체)을 다시 지칭) ⇒ 연결리스트에서 사용

struct student
{
	char * no;
	char * name;
	int grade;
	int class;
	struct student * p;
};

외부참조 구조체 (외부의 다른 구조체를 지칭) ⇒ 중첩구조체

struct student
{
	char * no;
	char * name;
	int grade;
	int class;
	struct score * p;
};

구조체 크기: 멤버변수의 크기만큼 구조체 크기가 결정됨




                  NOTE



패딩(Padding) 기법

의미 없는 공간 ⇒ Padding
메모리 정렬로 인해 4byte 단위로 컴파일하는 컴퓨터는 4byte 단위로 메모리를 구획하고 그 안에 멤버변수를 넣음
예) 멤버변수 int x; char a; → int(4byte) | 3byte(Padding) + char(1byte)



String (문자열)

배열 ← 문자열 저장: strcpy(배열변수, &quot;저장할 문자&quot; or 문자열이 저장된 변수);
char * 사용: char *test=&quot;hello&quot; → printf(&quot;%s&quot;, test);

size_t / ssize_t

size_t : unsigned int — sizeof() 연산자 사용 시 반환하는 타입
ssize_t : signed int — I/O(입출력)의 read/write에 사용. 실패 시 -1 반환 (성공 시 양수)




                  NOTE



ssize_t는 I/O가 일어날 때 반환값에 따라 error 처리를 할 수 있음


Extern (외부 변수 선언)

외부에 정의된 변수를 가져다 쓰겠다는 의미 (다른 파일에 정의되어 있음)

Typedef (구조체 별칭)

자료형 재정의

// 1. 기본 struct 선언
struct test{
    int num;
    char *name;
};
// 선언: struct test [변수];

// 2. typedef 사용
typedef struct test{
    int num;
    char *name;
}new_test;
// 선언: new_test [변수];

// 3. (2와 동일한 결과)
struct test{
    int num;
    char *name;
}typedef GG;
// 선언: GG [변수];
Typedef enum

특징

중복된 값 사용 불가
1로 정의 쉽게 가능
굳이 #define 사용 안 해도 됨



typedef enum{
    APP_NONE,
    APP_SCENE_1,
    APP_SCENE_2
}app_id_t;
구조체 심화 (도트 vs 화살표)



                  NOTE




구조체 포인터: 화살표(→) 접근
구조체 멤버변수: 도트(.) 접근
list 구조: 배열의 경우 인덱스 번호에 따라 포인터가 움직이는 형태

예) test.test_plus[i].name == test.(*test_plus + i).name







구조체 배열의 인덱스 접근 정리 (예: struct Arr *arr 멤버를 가진 구조체의 배열)

arr[0], arr[1], arr[2] … 는 각각 {name, price}를 가진 원소를 가리킴
test.arr[i].name == test.(*(arr + i)).name (인덱스 i만큼 포인터를 이동시켜 역참조 후 멤버 접근)



중첩구조체


struct Test{
	char * test;
	struct Test *test_plus;
}

struct Test test;
test.test_plus-&gt;name // test.(*test_plus).name 동일한 표현

구조체 배열 (리스트)

struct Test{
	char *name;
	struct Arr_test *test_plus;
}

struct Arr_test{
	int x;
}

struct Test test;

struct Test arr_test[10];
malloc(arr_test,sizeof(Test)*10)

//  A -&gt; B == (*A멤버변수).B멤버변수
// test_plus[i] == *(test_plus + i)
// test_plus[i].x == *(test_plus + i).x
printf(&quot;%d&quot;,test.test_plus[i].x);

구조체 포인터 (구조체 포인터 = &amp;구조체)

struct Test{
	char *name;
	struct Test * test_plus;
};

int main(){
	struct Test test;

	test.name = &quot;new&quot;;

	test.test_plus = &amp;test;
	printf(&quot;%s&quot;,test.test_plus-&gt;name) // new 출력

	retrun 0;
}

도트(.) vs 화살표(→)

도트연산자 . : 구조체 원소 접근
화살표연산자 -&gt; : 포인터를 사용하여 구조체 원소 접근



struct Test{
	char * name
	int year;
	int price;
	char *company;

	struct Test * test_plus;
}

int main (void){
	struct Test test;

	// 구조체 사용 도트 (test)
	test.name = &quot;game&quot;
	test.year = 1998;
	test.price = 10000;
	test.company = &quot;JSC&quot;;

	//구조체 사용 화살표 (test_plus)
	test.test_plus-&gt;name = &quot;new_game&quot;;
	test.test_plus-&gt;year = 2023;
	test.test_plus-&gt;price = 5000;
	test.test_plus-&gt;company = &quot;JS&quot;;

	//구조체 포인터
	stuct Test * test_pointer; //구조체 Test 포인터 생성
	test_pointer = &amp;test; //구조체 변수 test 주소

	test_pointer-&gt;name = &quot;pointer&quot;;
	test_pointer-&gt;year = 2020;
	test_pointer-&gt;price = 20000;
	test_pointer-&gt;company = &quot;Anlab&quot;;

	//구조체 포인터 안에 구조체
	test_pointer-&gt;test_plus-&gt;name = &quot;new_pointer&quot;;
	test_pointer-&gt;test_plus-&gt;year = 2021;
	test_pointer-&gt;test_plus-&gt;price = 0;
	test_pointer-&gt;test_plus-&gt;company = &quot;friend jiran&quot;;

개발-(cs)/언어/c언어/[cs]-포인터---핵심-개념-및-특징-정리.content:
포인터



                  NOTE



C 포인터 기본(배열 포인터, 포인터 연산)과 함수 포인터.


📌 개념
배열 포인터

char a[10] = {a,b,c,d,e,f,g,i,j,k};
포인터 선언

char *ptr;
ptr = a;
원래는 ptr = &amp;a 이지만 배열이므로 a로 선언


포인터 위치 변경: ptr = ptr + 3;




                  NOTE



현재 ptr은 ‘d’를 가리키고 있음
응용)
char *test = &quot;string&quot;;
char *ptr = test;
ptr += 3;
printf(&quot;%s&quot;, ptr); // → &quot;ing&quot; 출력 (주의: 움직여진 위치부터 문자열 출력)



*ptr = &#039;W&#039;;




                  NOTE



‘d’의 값이 → ‘W’로 변경
a → {a,b,c,W,e,f,g,h,i,j,k};


함수 포인터

형태: [함수 return 자료형] (*[포인터변수명])([인자 자료형]);

💻 예시
#include &lt;stdio.h&gt;

char* name_func(char* name){
    char *name_tmp=name;

    return name_tmp;
}

int main(void){

		char* (*name_func_p)(char* name);
    char *name=&quot;pwy&quot;;

    name_func_p=name_func;

    printf(&quot;%s\n&quot;,name_func(name));

    return 0;
}

개발-(cs)/언어/c언어/[cs]-함수---핵심-개념-및-특징-정리.content:
함수



                  NOTE



C 표준 문자열 함수(string.h), 동적 할당, 권한 체크, 매크로 정리.





                  NOTE



원문을 AI가 검토·보강함(사실 확인 권장).


📌 개념
문자열 함수 (String)
sprintf / snprintf (버퍼에 값 저장 → output 지정 가능)

sprintf(char str1[], &quot;%d&quot;, num); — 정수형을 문자열로 바꾸어 저장




                  NOTE



str1은 사이즈가 지정되어 있는 편이 좋음 (char *str1은 지양)



snprintf(버퍼, 크기, &quot;넣을값 + %?&quot;, %에 들어갈 변수); — 버퍼에 해당 값 저장

예) char cmd[128] = {0, }; snprintf(cmd, 128, &quot;kill -9 %d\n&quot;, getppid());






                  NOTE



system(char *cmd) — 쉘을 호출하여 cmd 명령어를 실행
⇒ snprintf로 버퍼에 명령을 만든 뒤 system(buffer);로 쉘에서 명령 실행 가능


strcat (문자 이어 붙이기)

strcat([배열1], [배열2]); — string1 + string2
예) strcat(const char *string1, const char *string2);




                  NOTE



인자가 const char *이므로 배열 사이즈가 지정되어 있어야 함수를 사용할 수 있음


#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

int main(void){
    char str_plus[10];

    for(int i=1; i&lt;73; i++){
        char str_[10]=&quot;U-2021-&quot;;
        sprintf(str_plus,&quot;%02d,&quot;,i);
        strcat(str_,str_plus);
        printf(&quot;%s&quot;,str_);
    }

    return 0;
}
strcpy (문자 복사)

strcpy([배열1], [배열2]); — 배열2 → 배열1로 복사
예) strcpy(char *string1, char *string2);

strcmp / strcasecmp (문자 비교)

strcmp(char *string1, char *string2); — 배열1, 배열2 비교

배열이 같으면: 0
배열1이 크면: 1 (양수)
배열2가 크면: -1 (음수)



strlen (문자 개수 출력)

