        String data;
        data = null;
        int result = data.length(); // NullPointerException 발생
    } catch (NullPointerException e){
        System.out.println(e.getMessage());
        // System.out.println(e.toString());
        // e.printStackTrace();
    }finally{
        System.out.println(&quot;마무리 실행&quot;);
