public class App {
    public static void main(String[] args) throws Exception {
        int[] arr = {2,4,1,3,5,6};
        mergeSort(arr, 0, arr.length - 1);
        printArray(arr);
    }

    private static void mergeSort(int[] arr, int startIndex, int endIndex){
        if (endIndex - startIndex &lt; 1){
            return;
        }
        int middleIndex =startIndex+ (endIndex -startIndex)/2;
        mergeSort(arr, startIndex, middleIndex);
        mergeSort(arr, middleIndex + 1, endIndex);

        int[] tmp = new int[arr.length];
        for(int i =startIndex; i&lt;= endIndex; i++){
            tmp[i] = arr[i];
        }

        int index1 = startIndex;
        int index2 = middleIndex+1;
        int sortIndex = startIndex;
        while(index1 &lt;= middleIndex &amp;&amp; index2 &lt;= endIndex){
            if( tmp[index1] &gt; tmp[index2] ){
                arr[sortIndex] = tmp[index2];
                index2++;
                sortIndex++;
            }else{
                arr[sortIndex] = tmp[index1];
                index1++;
                sortIndex++;
            }
        }

        while(index1 &lt;= middleIndex){
            arr[sortIndex] = tmp[index1];
            sortIndex++;
            index1++;
        }

        while(index2 &lt;= endIndex){
            arr[sortIndex] = tmp[index2];
            sortIndex++;
            index2++;
        }
    }

    private static void printArray(int[] arr){
        for (int i : arr) {
            System.out.println(i);
        }
    }
}

