public class App {
    private static final int SIZE = 5;
    public static void main(String[] args) throws Exception {

        int []arr = {1,3,4,2,5};

        for(int i =0; i&lt;SIZE; i++){
            int minIdx = i;
            for(int j = i+1; j&lt; SIZE; j++){
                if (arr[minIdx] &gt; arr[j]){
                    minIdx = j;
                }
            }
            if(i != minIdx){
                int temp = arr[minIdx];
                arr[minIdx] = arr[i];
                arr[i] = temp;
            }
        }

        for (int i : arr) {
            System.out.println(i);    
        }

    }
}

