        logic();
    }catch (SQLException e){

        if ( e.getErrorCode().isEqualTo(42122) ){
            // 42122는 &quot;SQL bad Grammer&quot; 오류 코드
            throw new DBErrorException(e);
        }else{
            throw new RuntimeException(e);
        }
    }

    //...

}
